import {
  drawArrow,
  drawCodeAnnotation,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  drawStepBox,
  drawTensor,
  Sel,
} from '../primitives';
import { ComputationGraph } from '../../graph/types';
import { ComponentDef } from '../../components/types';

export interface StepConfig {
  label: string;
  formula?: string;
  fill?: string;
  stroke?: string;
  matrices?: Array<{
    label: string;
    sublabel?: string;
    fill?: string;
    stroke?: string;
    w?: number;
    h?: number;
  }>;
  tensorGrid?: {
    rows: number;
    cols: number;
    label?: string;
  };
}

export interface ExplanationConfig {
  text: string;
  type: 'insight' | 'math' | 'perf' | 'warning';
}

export interface CodeConfig {
  title: string;
  desc?: string[];
  lines: string[];
}

export interface ComponentRenderConfig {
  title: string;
  paramSummary?: string;
  inputTensor: string;
  outputTensor: string;
  steps: StepConfig[];
  explanations: ExplanationConfig[];
  paramCount?: string;
  flops?: string;
  code: CodeConfig;
}

const STEP_COLORS = ['#4caf50', '#1976d2', '#7b1fa2', '#e65100', '#d32f2f', '#00838f'];
const STEP_FILLS = ['#e8f5e9', '#e3f2fd', '#f3e5f5', '#fff3e0', '#ffebee', '#e0f2f1'];

export function renderFromConfig(
  config: ComponentRenderConfig,
  g: Sel,
  _params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number } {
  const totalW = 800;
  const cx = totalW / 2;
  let y = 30;

  drawLabel(g, cx, y, config.title, { size: 16, weight: '700' });
  y += 22;

  if (config.paramSummary) {
    drawLabel(g, cx, y, config.paramSummary, { size: 10, color: '#888' });
    y += 28;
  }

  drawTensor(g, cx - 130, y, 260, 30, config.inputTensor, '#e8f5e9', '#4caf50');
  y += 50;

  config.steps.forEach((step, i) => {
    const color = STEP_COLORS[i % STEP_COLORS.length];
    const fill = step.fill || STEP_FILLS[i % STEP_FILLS.length];
    const stroke = step.stroke || color;

    drawArrow(g, cx, y - 20, cx, y, { color: '#78909c' });

    drawStepBox(g, cx - 140, y, 280, 46, step.label, {
      step: i + 1,
      fill,
      stroke,
      formula: step.formula,
    });
    y += 58;

    if (step.matrices && step.matrices.length > 0) {
      const gap = 10;
      const widths = step.matrices.map(m => m.w || 70);
      const heights = step.matrices.map(m => m.h || 50);
      const totalMW = widths.reduce((a, b) => a + b, 0) + (widths.length - 1) * gap;
      let mx = cx - totalMW / 2;
      step.matrices.forEach((m, mi) => {
        drawMatrixBlock(g, mx, y, {
          width: widths[mi],
          height: heights[mi],
          label: m.label,
          sublabel: m.sublabel,
          fill: m.fill || '#e3f2fd',
          stroke: m.stroke || '#1976d2',
        });
        mx += widths[mi] + gap;
      });
      y += Math.max(...heights) + 20;
    }
  });

  drawArrow(g, cx, y - 18, cx, y, { color: '#78909c' });
  drawTensor(g, cx - 130, y, 260, 30, config.outputTensor, '#e8f5e9', '#4caf50');
  y += 50;

  if (config.paramCount || config.flops) {
    const parts: string[] = [];
    if (config.paramCount) parts.push(`Params: ${config.paramCount}`);
    if (config.flops) parts.push(`FLOPs: ${config.flops}`);
    drawLabel(g, cx, y, parts.join('    '), { size: 11, color: '#1976d2', weight: '600' });
    y += 28;
  }

  config.explanations.forEach((exp) => {
    y = drawExplanation(g, 80, y, totalW - 160, exp.text, exp.type);
    y += 6;
  });

  y = drawCodeAnnotation(
    g,
    80,
    y,
    totalW - 160,
    config.code.title,
    config.code.desc || [],
    config.code.lines
  );

  return { width: totalW, height: y + 20 };
}
